     1	// The Recently done sessions row the developer chose (ADR 0008, Dashboard UI
     2	// concepts). Choosing a row selects; its Open control alone opens the
     3	// session (`./PageFrame.tsx`). A row linked to a published done story selects
     4	// that story as the page's Selected story in its project, keeping the
     5	// perspective; a standalone row selects its retained session and leaves the
     6	// Selected story, project and reading as they are. Neither changes the Side
     7	// panel.
     8	//
     9	// A story launch is linked when the done catalog its project publishes now
    10	// lists that exact story identity within the recent window Board Recently
    11	// done uses (`recentDoneRecords`). The shown project's current-revision
    12	// catalog is reused; another project's is read on demand through the same
    13	// authenticated snapshot and catalog readers, and no done record body is read.
    14	// An unread catalog is checking, and a failed one or one naming the story's
    15	// record as unreadable is unknown, each said apart from a confirmed miss,
    16	// which selects the session. A later choice, an explicit Open, or another
    17	// project chosen meanwhile supersedes an unanswered check. A linked row stays
    18	// chosen while its story is the page's Selected story.
    19	//
    20	// In Development the choice also shows its project's stories and brings into
    21	// view its done story's card, or, for a standalone row, its session's entry,
    22	// which is marked selected (`ChosenSessionOnPage`); the page's Recently done
    23	// range extends as far as that entry (`./sessionNavigation.ts`). Only the
    24	// current choice goes there, as the perspective is when its check answers.
    25	
    26	import {
    27	  createContext,
    28	  useCallback,
    29	  useLayoutEffect,
    30	  useRef,
    31	  useState,
    32	} from "react";
    33	import { doneRecordFileName } from "../../src/skills/dough-product-backlog/scripts/product-backlog-done-record.mjs";
    34	import { launchSubject, type LaunchRecord } from "./agentLaunch.ts";
    35	import { readDoneCatalogAt } from "./authenticatedDoneRead.ts";
    36	import { readPublishedSnapshot } from "./authenticatedRead.ts";
    37	import { recentDoneRecords, type DoneStories } from "./doneStories.ts";
    38	import {
    39	  sameSelectedStory,
    40	  type SelectedStory,
    41	  type usePageStorySelection,
    42	} from "./pageStorySelection.tsx";
    43	import type { PublishedSource } from "./publishedSource.ts";
    44	import type { PublishedWork } from "./publishedWork.ts";
    45	import type { GoToSession } from "./sessionNavigation.ts";
    46	import { sessionKey } from "./sessionReference.ts";
    47	
    48	// The chosen row, by its session key, and what its choice selected.
    49	export type RecentlyDoneChoice = { readonly key: string } & (
    50	  | { readonly kind: "checking" }
    51	  | { readonly kind: "linked"; readonly story: SelectedStory }
    52	  | { readonly kind: "standalone" }
    53	  | { readonly kind: "unknown"; readonly problem: string }
    54	);
    55	
    56	// A Recently done sessions row's selection: the chosen row, if any, and
    57	// choosing one.
    58	export type RecentlyDoneRowSelection = {
    59	  readonly choice: RecentlyDoneChoice | undefined;
    60	  readonly onSelect: (record: LaunchRecord) => void;
    61	};
    62	
    63	// The page's project facts the selection reads and moves.
    64	export type RecentlyDoneProjects = {
    65	  // The project the developer has chosen to show, read or not.
    66	  readonly selected: string;
    67	  // The selected project's snapshot, once read; its done catalog is reused.
    68	  readonly work: PublishedWork | undefined;
    69	  // Shows a project in the current perspective, as one history entry.
    70	  readonly select: (source: PublishedSource) => void;
    71	  // Whether the page shows the Development perspective.
    72	  readonly development: boolean;
    73	  // Shows a project's Development stories, as one history entry.
    74	  readonly show: (source: PublishedSource) => void;
    75	};
    76	
    77	// The session of the standalone row chosen, by its key, which its Board entry
    78	// marks selected.
    79	export const ChosenSessionOnPage = createContext<string | undefined>(undefined);
    80	
    81	type DoneLink = "linked" | "absent" | { readonly problem: string };
    82	
    83	// Whether the catalog lists the story recently done, lacks it, or cannot say.
    84	function linkIn(
    85	  done: Extract<DoneStories, { status: "catalogued" }>,
    86	  identity: string,
    87	): DoneLink {
    88	  if (
    89	    recentDoneRecords(done, new Date()).some(
    90	      (record) => record.identity === identity,
    91	    )
    92	  )
    93	    return "linked";
    94	  const fileName = doneRecordFileName(identity);
    95	  return done.unreadable.some((record) => record.fileName === fileName)
    96	    ? { problem: `Its done record ${fileName} could not be read.` }
    97	    : "absent";
    98	}
    99	
   100	// The shown project's done catalog, when it was read at the revision shown.
   101	function currentCatalog(work: PublishedWork | undefined, project: string) {
   102	  const done = work?.done;
   103	  return work?.source.id === project &&
   104	    done?.status === "catalogued" &&
   105	    done.revision === work.revision
   106	    ? done
   107	    : undefined;
   108	}
   109	
   110	async function readLink(
   111	  source: PublishedSource,
   112	  identity: string,
   113	  signal: AbortSignal,
   114	): Promise<DoneLink> {
   115	  try {
   116	    const { revision } = await readPublishedSnapshot(source, signal);
   117	    const catalog = await readDoneCatalogAt(source, revision, signal);
   118	    if (catalog.status === "gap") return { problem: catalog.problem };
   119	    return linkIn({ ...catalog, revision }, identity);
   120	  } catch (error) {
   121	    return { problem: error instanceof Error ? error.message : String(error) };
   122	  }
   123	}
   124	
   125	export function useRecentlyDoneSelection(
   126	  projects: readonly PublishedSource[],
   127	  stories: RecentlyDoneProjects,
   128	  selection: ReturnType<typeof usePageStorySelection>,
   129	  goTo: GoToSession,
   130	) {
   131	  const [choice, setChoice] = useState<RecentlyDoneChoice>();
   132	  const checking = useRef<AbortController | undefined>(undefined);
   133	  // The page as it is when an answer arrives, not as it was when chosen.
   134	  const now = useRef({ stories, goTo });
   135	  useLayoutEffect(() => {
   136	    now.current = { stories, goTo };
   137	  });
   138	
   139	  const abandonCheck = useCallback(() => {
   140	    checking.current?.abort();
   141	    checking.current = undefined;
   142	  }, []);
   143	  // Ends an unanswered check, whose row then shows no choice.
   144	  const supersede = useCallback(() => {
   145	    abandonCheck();
   146	    setChoice((current) =>
   147	      current?.kind === "checking" ? undefined : current,
   148	    );
   149	  }, [abandonCheck]);
   150	  // Another project chosen meanwhile keeps the developer where they went.
   151	  useLayoutEffect(supersede, [stories.selected, supersede]);
   152	
   153	  const select = (record: LaunchRecord) => {
   154	    abandonCheck();
   155	    const key = sessionKey(record.session);
   156	    const { identity } = launchSubject(record.request);
   157	    const source = projects.find(({ id }) => id === record.request.source);
   158	    // In Development, shows the session's project's stories and goes to the
   159	    // session, or its done `story`; elsewhere, gives up an earlier going.
   160	    const goThere = (story?: string) => {
   161	      const page = now.current;
   162	      if (!page.stories.development || source === undefined) {
   163	        page.goTo();
   164	        return;
   165	      }
   166	      page.stories.show(source);
   167	      page.goTo(record, story);
   168	    };
   169	    const standalone = () => {
   170	      setChoice({ key, kind: "standalone" });
   171	      goThere();
   172	    };
   173	    if (identity === undefined || source === undefined) {
   174	      standalone();
   175	      return;
   176	    }
   177	    const story = { project: source.id, identity };
   178	    const settle = (link: DoneLink) => {
   179	      if (link === "absent") {
   180	        standalone();
   181	      } else if (link === "linked") {
   182	        setChoice({ key, kind: "linked", story });
   183	        selection.api.select(story);
   184	        if (now.current.stories.development) goThere(identity);
   185	        else now.current.stories.select(source);
   186	      } else {
   187	        setChoice({ key, kind: "unknown", problem: link.problem });
   188	        now.current.goTo();
   189	      }
   190	    };
   191	    const shown = currentCatalog(stories.work, source.id);
   192	    if (shown !== undefined) {
   193	      settle(linkIn(shown, identity));
   194	      return;
   195	    }
   196	    const controller = new AbortController();
   197	    checking.current = controller;
   198	    setChoice({ key, kind: "checking" });
   199	    goTo();
   200	    void readLink(source, identity, controller.signal).then((link) => {
   201	      if (checking.current !== controller) return;
   202	      checking.current = undefined;
   203	      settle(link);
   204	    });
   205	  };
   206	
   207	  const chosen =
   208	    choice?.kind === "linked" &&
   209	    !sameSelectedStory(selection.selected, choice.story)
   210	      ? undefined
   211	      : choice;
   212	  const row: RecentlyDoneRowSelection = { choice: chosen, onSelect: select };
   213	  const chosenSession = chosen?.kind === "standalone" ? chosen.key : undefined;
   214	  return { choice: chosen, row, supersede, chosenSession };
   215	}
     1	// A Recently done sessions row's done-story check
     2	// (../../src/recentlyDoneSelection.ts): an unanswered check is said apart
     3	// from a confirmed miss and is superseded by a later choice; a failed one
     4	// leaves the reading and the session's access as they were.
     5	
     6	import { expect, test } from "../dashboardTest.ts";
     7	import { parts } from "../dashboardPage.ts";
     8	import { expectProjectChoice } from "../projectChoice.ts";
     9	import {
    10	  adHoc,
    11	  choiceStatus,
    12	  linked,
    13	  openSelectionPage,
    14	} from "../recentlyDoneSelectionJourney.ts";
    15	import {
    16	  holdPygardonCatalog,
    17	  isPygardonCatalog,
    18	  pygardonCatalogRead,
    19	} from "../pygardonCatalogReads.ts";
    20	
    21	test.use({ projectFolders: ["open-dough", "doughnut", "pygardon"] });
    22	
    23	test("an unanswered check is superseded by a later choice, and a failed one leaves the reading with its session's Open usable", async ({
    24	  page,
    25	  dashboard,
    26	}) => {
    27	  const { shown, row } = await openSelectionPage(page, dashboard);
    28	  const { development, intentChoice, intent } = parts(page);
    29	  await intentChoice.click();
    30	  await expect(intent).toBeVisible();
    31	
    32	  await test.step("while Pygardon's catalog is unread the row says it is checking; choosing another row abandons that read", async () => {
    33	    const held = await holdPygardonCatalog(page);
    34	    const abandoned = page.waitForEvent("requestfailed", (request) =>
    35	      isPygardonCatalog(new URL(request.url())),
    36	    );
    37	    try {
    38	      await shown.entry(linked.title).click();
    39	      await held.asked;
    40	      await expect(choiceStatus(row(linked.title))).toHaveText(
    41	        "Checking for its published done story…",
    42	      );
    43	      await expect(shown.entry(linked.title)).toHaveAttribute(
    44	        "aria-pressed",
    45	        "true",
    46	      );
    47	      await shown.entry(adHoc.title).click();
    48	      await abandoned;
    49	    } finally {
    50	      held.release();
    51	    }
    52	    await expect(shown.entry(adHoc.title)).toHaveAttribute(
    53	      "aria-pressed",
    54	      "true",
    55	    );
    56	    await expect(shown.entry(linked.title)).toHaveAttribute(
    57	      "aria-pressed",
    58	      "false",
    59	    );
    60	    await expect(choiceStatus(row(linked.title))).toHaveCount(0);
    61	    await expectProjectChoice(page, "Open Dough");
    62	    await expect(intentChoice).toBeChecked();
    63	    await expect(intent).not.toHaveAttribute("data-selected-story");
    64	    await page.unrouteAll({ behavior: "wait" });
    65	  });
    66	
    67	  await test.step("a failed catalog read says so apart from a miss and leaves project and story alone", async () => {
    68	    await page.route(isPygardonCatalog, (route) =>
    69	      route.fulfill({
    70	        status: 502,
    71	        json: { error: "GitHub could not be reached." },
    72	      }),
    73	    );
    74	    const read = pygardonCatalogRead(page);
    75	    await shown.entry(linked.title).click();
    76	    await read;
    77	    await expect(choiceStatus(row(linked.title))).toContainText(
    78	      "Its published done story could not be checked.",
    79	    );
    80	    await expect(choiceStatus(row(linked.title))).toContainText(
    81	      "Select again to check again.",
    82	    );
    83	    await expect(shown.entry(linked.title)).toHaveAccessibleDescription(
    84	      /could not be checked/,
    85	    );
    86	    await expectProjectChoice(page, "Open Dough");
    87	    await expect(intentChoice).toBeChecked();
    88	    await expect(intent).not.toHaveAttribute("data-selected-story");
    89	  });
    90	
    91	  await test.step("its Open still opens the session's terminal", async () => {
    92	    await shown.open(linked.title).click();
    93	    const terminal = page.getByRole("region", { name: "Terminal" });
    94	    await expect(terminal.getByRole("heading")).toHaveText(linked.title);
    95	    await expect(development).toBeChecked();
    96	    await expect.poll(() => dashboard.claudeAttaches()).toHaveLength(1);
    97	  });
    98	});
